CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,property_code text NOT NULL,name text NOT NULL,location_name text NOT NULL,google_maps_url text,room_type text NOT NULL,beds integer NOT NULL DEFAULT 1 CHECK(beds>=0),bathrooms numeric(5,1) NOT NULL DEFAULT 1 CHECK(bathrooms>=0),max_guests integer NOT NULL CHECK(max_guests>0),features jsonb NOT NULL DEFAULT '[]'::jsonb,photos jsonb NOT NULL DEFAULT '[]'::jsonb,weekday_price_minor bigint NOT NULL DEFAULT 0 CHECK(weekday_price_minor>=0),weekend_price_minor bigint NOT NULL DEFAULT 0 CHECK(weekend_price_minor>=0),deposit_minor bigint NOT NULL DEFAULT 0 CHECK(deposit_minor>=0),cleaning_fee_minor bigint NOT NULL DEFAULT 0 CHECK(cleaning_fee_minor>=0),check_in_time text NOT NULL DEFAULT '15:00',check_out_time text NOT NULL DEFAULT '11:00',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,property_code));CREATE INDEX properties_search_idx ON properties(tenant_id,active,location_name,max_guests);
CREATE TABLE property_stays(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,property_id uuid NOT NULL,customer_id uuid,check_in date NOT NULL,check_out date NOT NULL,guest_count integer NOT NULL CHECK(guest_count>0),status text NOT NULL DEFAULT 'CONFIRMED' CHECK(status IN('PENDING','CONFIRMED','CANCELLED','COMPLETED')),source text NOT NULL DEFAULT 'ADMIN',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(check_out>check_in),FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id) ON DELETE SET NULL,UNIQUE(tenant_id,id));
ALTER TABLE property_stays ADD CONSTRAINT property_stays_no_overlap EXCLUDE USING gist (tenant_id WITH =,property_id WITH =,daterange(check_in,check_out,'[)') WITH &&) WHERE (status IN('PENDING','CONFIRMED'));
